const battlePassMapTargets=[['Customs','customs'],['Factory','factory'],['Ground Zero','ground-zero'],['Interchange','interchange'],['Lighthouse','lighthouse'],['Reserve','reserve'],['Shoreline','shoreline'],['Streets of Tarkov','streets-of-tarkov'],['The Labyrinth','the-lab'],['The Lab','the-lab'],['Woods','woods']];
function linkBattlePassMaps(){document.querySelectorAll('.bp-doc-card:not([data-map-links])').forEach(card=>{const description=card.querySelector('p')?.textContent||'',targets=battlePassMapTargets.filter(([name])=>description.includes(name));card.dataset.mapLinks='ready';if(!targets.length)return;const guide=document.createElement('section');guide.className='bp-map-guide';guide.innerHTML='<b>Como procurar</b><small>Abra o mapa indicado e use os marcadores disponíveis. A base ainda não possui uma coordenada verificada para este documento.</small><div>'+targets.map(([name,slug])=>'<button type="button" data-map="'+slug+'">Abrir '+name+'</button>').join('')+'</div>';guide.querySelectorAll('button[data-map]').forEach(button=>button.onclick=()=>{pendingMapName=button.dataset.map;document.querySelector('#nav button[data-page="mapa"]')?.click()});card.append(guide)})}
