function decorateTacticalDashboard(){
  const grid=content.querySelector('.grid');
  if(!grid||grid.dataset.tacticalDecor)return;
  grid.dataset.tacticalDecor='ready';
  const values=[...grid.querySelectorAll(':scope > .card:not(.wide) .num')].map(element=>element.textContent.trim());
  if(values.length<4)return;
  const strip=document.createElement('section');strip.className='command-strip';
  strip.innerHTML='<div class="command-strip-title"><b>PAINEL OPERACIONAL</b><small>INTEL LOCAL · PRONTO PARA PLANEJAMENTO</small></div><div class="command-strip-metrics"><span>Em andamento<b>'+values[0]+'</b></span><span>Oportunidades<b>'+values[1]+'</b></span><span>Concluídas<b>'+values[2]+'</b></span><span>Alertas<b>'+values[3]+'</b></span></div>';
  grid.prepend(strip);
}
