async function hideout(){
  content.innerHTML='<div class="placeholder"><b>Preparando o Hideout…</b>Organizando estações, níveis e materiais do cache local.</div>';
  const [stations,saved]=await Promise.all([window.tarkas.hideoutCatalog('regular'),window.tarkas.getSetting('hideoutLevels','{}')]);
  let levels={};try{levels=JSON.parse(saved)||{}}catch{}
  if(!stations.length){content.innerHTML='<div class="placeholder"><b>Os dados do Hideout ainda não estão disponíveis.</b>Use “Atualizar dados” na Visão Geral e tente novamente.</div>';return}
  content.replaceChildren();
  const hero=document.createElement('section');hero.className='hideout-hero';hero.innerHTML='<div><small>PLANEJADOR DE ESCONDERIJO</small><h2>Hideout</h2><p>Acompanhe cada estação e veja exatamente o que falta para o próximo nível.</p></div>';
  const summary=document.createElement('div');summary.className='hideout-summary';hero.append(summary);content.append(hero);
  const layout=document.createElement('div');layout.className='hideout-layout';const grid=document.createElement('section');grid.className='hideout-grid';const detail=document.createElement('section');detail.className='hideout-detail';layout.append(grid,detail);content.append(layout);let selected=stations[0].id;
  const done=()=>stations.reduce((total,station)=>total+Math.min(Number(levels[station.id])||0,station.levels.length),0),total=()=>stations.reduce((all,station)=>all+station.levels.length,0),save=()=>window.tarkas.saveSetting('hideoutLevels',JSON.stringify(levels)).catch(()=>{});
  const drawSummary=()=>summary.innerHTML='<b>'+done()+'/'+total()+'</b><span>níveis registrados</span>';
  const drawDetail=()=>{const station=stations.find(item=>item.id===selected)||stations[0],current=Math.max(0,Math.min(Number(levels[station.id])||0,station.levels.length)),next=station.levels.find(item=>item.level===current+1);detail.replaceChildren();const head=document.createElement('header');if(station.image){const image=document.createElement('img');image.src=station.image;image.alt='';image.loading='lazy';head.append(image)}const info=document.createElement('div');info.innerHTML='<small>ESTAÇÃO SELECIONADA</small><h2></h2><p>Nível atual: '+current+' de '+station.levels.length+'</p>';info.querySelector('h2').textContent=station.name;head.append(info);detail.append(head);const control=document.createElement('label');control.className='hideout-level-control';control.append('Registrar nível atual');const select=document.createElement('select');for(let level=0;level<=station.levels.length;level++){const option=document.createElement('option');option.value=level;option.textContent=level===0?'Ainda não construída':'Nível '+level;option.selected=level===current;select.append(option)}select.onchange=()=>{levels[station.id]=Number(select.value);save();drawSummary();drawGrid();drawDetail()};control.append(select);detail.append(control);const body=document.createElement('section');body.className='hideout-requirements';if(!next){body.innerHTML='<h3>Estação no máximo</h3><p>Todos os níveis desta estação foram registrados como concluídos.</p>'}else{const title=document.createElement('h3');title.textContent='Próximo: nível '+next.level;body.append(title);if(next.description){const description=document.createElement('p');description.textContent=next.description;body.append(description)}const materials=document.createElement('div');materials.className='hideout-materials';if(next.items.length)next.items.forEach(item=>{const row=document.createElement('article');if(item.icon){const image=document.createElement('img');image.src=item.icon;image.alt='';image.loading='lazy';row.append(image)}else row.append(document.createElement('i'));const name=document.createElement('span');name.textContent=item.name+(item.foundInRaid?' · FIR':'');const count=document.createElement('b');count.textContent='×'+item.count;row.append(name,count);materials.append(row)});else materials.innerHTML='<small>Sem materiais de item registrados para este nível.</small>';body.append(materials);if(next.constructionTime){const time=document.createElement('small');time.className='hideout-time';time.textContent='Tempo de construção: '+Math.round(next.constructionTime/60)+' min';body.append(time)}}detail.append(body)};
  const drawGrid=()=>grid.replaceChildren(...stations.map(station=>{const current=Math.max(0,Math.min(Number(levels[station.id])||0,station.levels.length)),card=document.createElement('button');card.type='button';card.className='hideout-station'+(station.id===selected?' active':'');const name=document.createElement('b');name.textContent=station.name;const progress=document.createElement('span');progress.textContent='Nível '+current+' / '+station.levels.length;const meter=document.createElement('i');meter.style.setProperty('--progress',(station.levels.length?current/station.levels.length:0)*100+'%');card.append(name,progress,meter);card.onclick=()=>{selected=station.id;drawGrid();drawDetail()};return card}));
  drawSummary();drawGrid();drawDetail();
}
