  const updated=status.last?.updatedAt?new Date(status.last.updatedAt).toLocaleString('pt-BR'):'data não disponível';const stats=document.createElement('section');stats.className='market-stats';stats.innerHTML='<span><b>'+items.length.toLocaleString('pt-BR')+'</b> itens indexados</span><span><b>'+favorites.size+'</b> favoritos</span><span>Abra um item para ver usos e fontes.</span><span>Dados atualizados: '+updated+'</span>';content.append(stats);const categories=document.createElement('section');categories.className='item-categories';const categoryList=[['all','Todos'],['gun','Armas'],['ammo','Munições'],['armor','Armaduras'],['helmet','Capacetes'],['meds','Medicina'],['keys','Chaves'],['provisions','Provisões'],['barter','Itens de troca'],['mods','Mods']];categoryList.forEach(([type,label])=>{const button=document.createElement('button');button.type='button';button.textContent=label;button.dataset.type=type;button.className=type==='all'?'active':'';button.onclick=()=>{selectedType=type;categories.querySelectorAll('button').forEach(item=>item.classList.toggle('active',item===button));draw()};categories.append(button)});content.append(categories);
