async function addRaidPerformance(){const anchor=document.querySelector('.raid-history-panel');if(!anchor||anchor.dataset.performance)return;anchor.dataset.performance='ready';const raids=await window.tarkas.raidHistory();const panel=document.createElement('section');panel.className='raid-performance';const survived=raids.filter(raid=>raid.result==='survived').length,loot=raids.reduce((sum,raid)=>sum+(Number(raid.loot_value)||0),0),kills=raids.reduce((sum,raid)=>sum+(Number(raid.kills)||0),0),rate=raids.length?Math.round(survived/raids.length*100):0;panel.innerHTML='<small>DESEMPENHO DE RAIDS</small><div><span><b>'+raids.length+'</b> raids</span><span><b>'+rate+'%</b> sobrevivência</span><span><b>'+loot.toLocaleString('pt-BR')+' ₽</b> loot</span><span><b>'+kills+'</b> eliminações</span></div>';const maps=new Map();raids.forEach(raid=>{const value=maps.get(raid.map_name)||{total:0,survived:0};value.total++;if(raid.result==='survived')value.survived++;maps.set(raid.map_name,value)});if(maps.size){const byMap=document.createElement('p');byMap.className='raid-map-breakdown';byMap.textContent=[...maps].map(([map,value])=>map+' '+Math.round(value.survived/value.total*100)+'% ('+value.total+')').join(' · ');panel.append(byMap)}anchor.insertAdjacentElement('afterend',panel)}
