async function addRaidKits(){const anchor=document.querySelector('.raid-performance')||document.querySelector('.raid-history-panel');if(!anchor||anchor.dataset.kits)return;anchor.dataset.kits='ready';const panel=document.createElement('section');panel.className='raid-kits-panel';panel.innerHTML='<h3>Kits de raid</h3><form><input required maxlength="100" placeholder="Nome do kit"><textarea required maxlength="800" placeholder="Itens, separados por vírgula"></textarea><button class="qaction">Salvar kit</button></form><div></div>';const list=panel.querySelector('div');const draw=async()=>{const kits=await window.tarkas.raidKits();list.replaceChildren();if(!kits.length){list.innerHTML='<small class="muted">Nenhum kit salvo.</small>';return}for(const kit of kits){const row=document.createElement('article');const title=document.createElement('b');title.textContent=kit.name;let checks=[];try{checks=JSON.parse(await window.tarkas.getSetting('kitChecks:'+kit.id,'[]'))||[]}catch{}const checklist=document.createElement('section');checklist.className='kit-checklist';kit.items.forEach((item,index)=>{const label=document.createElement('label'),box=document.createElement('input'),text=document.createElement('span');box.type='checkbox';box.checked=Boolean(checks[index]);text.textContent=item;box.onchange=async()=>{checks[index]=box.checked;await window.tarkas.saveSetting('kitChecks:'+kit.id,JSON.stringify(checks))};label.append(box,text);checklist.append(label)});const reset=document.createElement('button');reset.type='button';reset.className='qaction kit-reset';reset.textContent='Limpar';reset.onclick=async()=>{await window.tarkas.saveSetting('kitChecks:'+kit.id,'[]');draw()};const remove=document.createElement('button');remove.type='button';remove.className='qaction';remove.textContent='Excluir';remove.onclick=async()=>{await window.tarkas.removeRaidKit(kit.id);draw()};row.append(title,checklist,reset,remove);list.append(row)}};panel.querySelector('form').onsubmit=async event=>{event.preventDefault();const f=event.currentTarget.elements;await window.tarkas.saveRaidKit(f[0].value,f[1].value.split(','));f[0].value='';f[1].value='';draw()};anchor.insertAdjacentElement('afterend',panel);await draw()}
